#include <stdio.h>
int f(int a, int b) {
    return a - b * 3;
}
int main()
{
    int a = 3;
    for(int i=0 ; i<4 ; i++) {
        a = f(a, -i);
        a = f(a, i);
    }
    printf("%d\n", a);
    return 0;
}

